/* Simplified from sudo set_cmnd() argument handling, pre-patch. */
for (size = 0, av = argv + 1; *av; av++)
    size += strlen(*av) + 1;
user_args = malloc(size);

for (to = user_args, av = argv + 1; (from = *av); av++) {
    while (*from) {
        if (from[0] == '\\' && !isspace((unsigned char)from[1]))
            from++;                 /* skip the escaping backslash */
        *to++ = *from++;            /* copy the next character */
    }
    *to++ = ' ';
}

